import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Img } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FoundersIncAnimationProps = Record<string, any>;

const FoundersIncAnimation: React.FC<FoundersIncAnimationProps> = ({
  titleText = "Founders, Inc",
  fontSize = 100,
  textColor = "#ffffff",
  letterSpacing = 2,
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  image1 = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=400&q=80",
  image2 = "https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=400&q=80",
  image3 = "https://images.unsplash.com/photo-1542831371-29b0f74f9713?auto=format&fit=crop&w=400&q=80",
}) => {
  
  {/* Load Google Fonts */ }
  useFontLoader(["Instrument Serif"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Split text for staggered animation
  const chars = React.useMemo(() => titleText.split(""), [titleText]);
  const images = [image1, image2, image3];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
      <div
        style={{
          fontFamily: "Instrument Serif",
          fontSize: fontSize,
          color: textColor,
          letterSpacing: letterSpacing,
          display: 'flex',
          flexDirection: 'row',
          flexWrap: 'wrap',
          justifyContent: 'center',
          alignItems: 'center',
          width: '100%',
          padding: '0 40px',
          marginBottom: 40, // Space between text and cards
          zIndex: 10,
        }}
      >
        {chars.map((char, i) => {
          // Stagger delay based on index
          const delay = i * 4; 
          
          // Spring physics for entrance
          const entranceSpring = spring({
            frame: frame - delay,
            fps,
            config: {
              damping: 12,
              stiffness: 100,
              mass: 0.8,
            },
          });

          // Interpolate values
          const opacity = interpolate(entranceSpring, [0, 1], [0, 1]);
          const translateY = interpolate(entranceSpring, [0, 1], [40, 0]);
          const rotateX = interpolate(entranceSpring, [0, 1], [90, 0]);
          const scale = interpolate(entranceSpring, [0, 1], [0.8, 1]);

          return (
            <span
              key={i}
              style={{
                opacity,
                transform: `translateY(${translateY}px) rotateX(${rotateX}deg) scale(${scale})`,
                transformOrigin: 'bottom center',
                display: 'inline-block',
                whiteSpace: 'pre', // Preserve spaces
                transition: "none", // STRICT RULE: No CSS transitions
              }}
            >
              {char}
            </span>
          );
        })}
      </div>

      {/* Floating Cards Container */}
      <div style={{ display: 'flex', gap: 30, justifyContent: 'center', alignItems: 'center', perspective: 1000 }}>
        {images.map((imgSrc, index) => {
          const cardDelay = 20 + index * 6; // Start after text begins
          
          // Spring entrance
          const cardSpring = spring({
            frame: frame - cardDelay,
            fps,
            config: { damping: 14, stiffness: 80 },
          });

          // Entrance Interpolations
          const opacity = interpolate(cardSpring, [0, 1], [0, 1]);
          const scale = interpolate(cardSpring, [0, 1], [0.5, 1]);
          const entranceY = interpolate(cardSpring, [0, 1], [100, 0]);
          
          // Continuous floating effect
          const floatOffset = Math.sin((frame - cardDelay) / 20) * 10;
          // Only float after fully entered (roughly) or mix it in. 
          // Adding it directly creates a nice organic motion during entry too.
          
          const totalY = entranceY + floatOffset;

          return (
            <div
              key={`card-${index}`}
              style={{
                width: 200,
                height: 280,
                borderRadius: 12,
                overflow: 'hidden',
                boxShadow: '0 10px 30px rgba(0,0,0,0.3)',
                opacity,
                transform: `translateY(${totalY}px) scale(${scale})`,
                transition: "none",
                backgroundColor: '#1a1a1a',
                border: `1px solid ${textColor}33`,
              }}
            >
              <Img
                src={imgSrc}
                style={{
                  width: '100%',
                  height: '100%',
                  objectFit: 'cover',
                }}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FoundersIncAnimation;